// Dev run of the Electron shell on a synthetic demo only (never the owner's real data):
//   pnpm --filter @cashu/desktop dev
// The demo is native synthetic vaults generated by apps/host/src/testing/devDemo.ts: no Python and no
// OS keychain. When the data dir (default ~/cashu-lab/desktop-demo, CASHU_DATA_DIR overrides) does not
// exist, `devDemo.ts init` creates it with two profiles (demo-anna, demo-piotr) dated relative to
// today; delete the dir to generate a fresh one. `devDemo.ts serve` then starts the data dir's
// synthetic host, this script waits until it is ready and launches Electron, which connects to that
// host (it starts a production host only when none runs), and stops the host when Electron exits.
// A host left running for the data dir is stopped with
// `node --import tools/node-ts/resolveTs.ts apps/host/src/cli.ts stop --data-dir <dir>`.
import { spawn, spawnSync } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import electron from "electron";

const here = dirname(fileURLToPath(import.meta.url));
const app = resolve(here, "..");
const repo = resolve(app, "..", "..");
const lab = join(homedir(), "cashu-lab");
const READY_TIMEOUT_MS = 30_000;

const env = {
  ...process.env,
  CASHU_DATA_DIR: process.env.CASHU_DATA_DIR || join(lab, "desktop-demo"),
  CASHU_WORKSPACES_DIR: process.env.CASHU_WORKSPACES_DIR || join(lab, "desktop-demo-ws"),
  CASHU_AUTO_DAILY: "0",
  // The shell refuses a data dir outside this folder.
  CASHU_DESKTOP_ALLOWED_DATA_ROOT: process.env.CASHU_DESKTOP_ALLOWED_DATA_ROOT || lab,
};
const dataDir = resolve(env.CASHU_DATA_DIR);

const devDemo = (mode) => [
  "--disable-warning=ExperimentalWarning",
  "--experimental-strip-types",
  "--import",
  join(repo, "tools", "node-ts", "resolveTs.ts"),
  join(repo, "apps", "host", "src", "testing", "devDemo.ts"),
  mode,
  dataDir,
];

if (!existsSync(dataDir)) {
  const init = spawnSync(process.execPath, devDemo("init"), { env, stdio: "inherit" });
  if (init.status !== 0) process.exit(init.status ?? 1);
} else if (!existsSync(join(dataDir, "dev-demo.json"))) {
  console.error(
    `${dataDir} is not a devDemo data dir (an older demo?). Remove it, or set CASHU_DATA_DIR to a new folder.`,
  );
  process.exit(1);
}

const build = spawnSync("pnpm", ["run", "build"], { cwd: app, stdio: "inherit" });
if (build.status !== 0) process.exit(build.status ?? 1);

let stopping = false;
let shell = null;
const host = spawn(process.execPath, devDemo("serve"), { env, stdio: "inherit" });
const hostExit = new Promise((done) => host.once("exit", (code) => done(code)));
void hostExit.then((code) => {
  if (stopping) return;
  console.error(
    `The demo host exited (${code}). If another host runs for ${dataDir}, stop it (see the header of this script).`,
  );
  stopping = true;
  shell?.kill("SIGTERM");
  process.exit(code || 1);
});

const readyFile = join(dataDir, "dev-demo-ready");
const deadline = Date.now() + READY_TIMEOUT_MS;
for (;;) {
  let ready = false;
  try {
    ready = readFileSync(readyFile, "utf8") === `${host.pid}\n`;
  } catch {}
  if (ready) break;
  if (Date.now() > deadline) {
    console.error("The demo host did not become ready in time.");
    stopping = true;
    host.kill("SIGTERM");
    process.exit(1);
  }
  await new Promise((done) => setTimeout(done, 100));
}

shell = spawn(electron, [app, ...process.argv.slice(2)], { env, stdio: "inherit" });
shell.on("exit", async (code) => {
  stopping = true;
  host.kill("SIGTERM");
  const timer = setTimeout(() => host.kill("SIGKILL"), 10_000);
  await hostExit;
  clearTimeout(timer);
  process.exit(code ?? 0);
});
for (const signal of ["SIGINT", "SIGTERM"])
  process.on(signal, () => {
    stopping = true;
    shell?.kill(signal);
  });
